def calc_bmi(height_cm, weight):
    return weight / (height_cm / 100) ** 2


def judge(bmi):
    if bmi < 18.5:
        return "저체중"
    elif bmi < 23:
        return "정상"
    elif bmi < 25:
        return "과체중"
    return "비만"


height, weight = map(float, input().split())
bmi = calc_bmi(height, weight)
print(f"BMI: {bmi:.1f}")
print(f"판정: {judge(bmi)}")
